"""Freeze implementation sources and asset hashes, without copying private art."""
import argparse,hashlib,json,subprocess,re
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--ios',required=True,type=Path);p.add_argument('--mac',required=True,type=Path);p.add_argument('--output',required=True,type=Path);a=p.parse_args()
def revision(root):return subprocess.check_output(['git','rev-parse','HEAD'],cwd=root,text=True).strip()
def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
paths=['Mobile/Sources/App/GameViewController.swift','Mobile/Sources/App/MachineCanvas.swift','Mobile/Sources/App/MechanicalKeys.swift','Mobile/Sources/App/CoverLoader.swift','Mobile/Sources/App/EmulationSession.swift','Mobile/Sources/Rendering/SpatialCanvas.swift','Mobile/Sources/Rendering/SpatialMachine.swift','Mobile/Sources/Domain/DeviceLayout.swift','Mobile/Sources/Domain/DeviceModel.swift','Mobile/Sources/Domain/PickerMotion.swift','Mobile/Sources/Domain/GameCatalog.swift','Mobile/Sources/Domain/ROMLibrary.swift']
assets={str(f.relative_to(a.ios)):sha(f) for directory in ['Assets/Branding','Assets/Logos','Assets/Skins/Spatial','Assets/Patterns','Assets/Sounds'] for f in sorted((a.ios/directory).rglob('*')) if f.is_file() and f.name!='.DS_Store'}
for name in ['Assets/media-slots.json','Assets/Skins/spatial-manifest.json']:
 if (a.ios/name).exists():assets[name]=sha(a.ios/name)
models=(a.ios/'Mobile/Sources/Domain/DeviceModel.swift').read_text()
themes={name:json.loads('['+items+']') for name,items in re.findall(r'case \.(\w+): return \[([^]]+)\]',models)}
data={'schema':1,'frozen_on':'2026-10-27','authority':'Latest user requirements override historical defects; this snapshot is an implementation reference, not Android acceptance.','ios_revision':revision(a.ios),'mac_revision':revision(a.mac),'sources':{name:sha(a.ios/name) for name in paths},'private_asset_hashes':assets,'themes':themes,'layout':{'projection':'orthographic','phone_models':['gba','gbc','psp'],'tablet_models':['nds','gba','gbc','psp','3ds'],'theme_heading_position':'top, beneath model name','theme_heading_model_font_pt':17.5,'theme_heading_theme_font_pt':13.5,'phone_preview_width_safe_fraction':0.76,'tablet_preview_width_safe_fraction':0.9,'theme_crossfade_seconds':0.28,'page_controls':{'tap_target_page':True,'continuous_scrub':True,'hide_single':True,'one_step_per_swipe':True}},'motion':{'idle_period_seconds':8.5,'yaw_radians':0.18,'pitch_radians':0.055,'button_transition_seconds':0.075,'cartridge_insert_seconds':1.65,'psp_insert_seconds':2.95,'psp_door_radians':1.18,'psp_phases':{'open':[0,0.18],'seat':[0.18,0.65],'close':[0.68,0.84],'read':[0.86,1]}},'rendering':{'ambient_apple_intensity':130,'key_apple_intensity':460,'fill_apple_intensity':120,'spot_apple_intensity':200,'warning':'Apple light units must be calibrated in Android, not copied numerically as Filament lux.'},'android_acceptance':{'product_visual_pages_passed':0,'prototype_is_product_baseline':False,'phone_device':'OPPO PGEM10','physical_tablet_available':False},'historical_screenshots':{'Structure-2026-10-25/iphone-gba-theme-0.png':'visual reference; reconcile with current source and latest user feedback','Physical-Interaction-2026-10-24/iphone-gba-library.png':'DO NOT copy old tiny cover / loose metadata layout; superseded by later requirements'}}
a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n');print('Baseline:',len(paths),'sources;',len(assets),'asset hashes; no artwork copied')
